function findingOf(comment){
  const lines=comment.body.split("\n").map(x=>x.trim()).filter(Boolean);
  return lines.find(x=>/^P[0-9]:/.test(x)) ?? lines[0] ?? "No finding text";
}
function toolOf(login){
  if(login.includes("advanced-security")) return "GitHub Advanced Security";
  if(login.includes("code-quality")) return "GitHub Code Quality";
  if(login.includes("chatgpt-codex")) return "Codex Review";
  if(login.includes("pullfrog")) return "Pullfrog";
  if(login.includes("cubic")) return "Cubic";
  return login;
}
const groups=new Map();
for(const comment of inline){
  const finding=findingOf(comment);
  const apiBase = finding.includes("apiBasePath") && (
    comment.path==="superconsole/src/lib/components/admin-api.ts" ||
    comment.path==="superconsole/src/lib/server/transport.ts"
  );
  const key=apiBase ? "cross-tool:superconsole-api-base-path" : `${comment.path}\0${finding}`;
  let group=groups.get(key);
  if(!group){
    group={finding,comments:[],tools:new Set(),locations:[],primaryTool:toolOf(comment.user.login)};
    groups.set(key,group);
  }
  group.comments.push(comment.id);
  group.tools.add(toolOf(comment.user.login));
  group.locations.push({path:comment.path,line:comment.line,originalLine:comment.original_line,url:comment.html_url});
  if(apiBase && toolOf(comment.user.login)==="Pullfrog"){
    group.primaryTool="Pullfrog";
    group.finding=finding;
  }
}
function severityOf(group){
  const f=group.finding;
  if(group.primaryTool==="GitHub Advanced Security") return "High";
  if(group.primaryTool==="GitHub Code Quality") return "Low";
  if(/\bP1\b|P1:/.test(f)) return "High";
  if(f.startsWith("**Security:**")) return "High";
  if(f.includes("apiBasePath")) return "High";
  return "Medium";
}
function cleanTitle(text){
  return text
    .replace(/<[^>]*>/g,"")
    .replace(/!\[[^\]]*\]\([^)]*\)/g,"")
    .replace(/^#+\s*/,"")
    .replace(/^\*\*Security:\*\*\s*/,"")
    .replace(/^P[0-9]:\s*/,"")
    .replace(/\*\*/g,"")
    .trim()
    .split(/(?<=[.!?])\s+/)[0]
    .slice(0,180);
}
function fixOf(group){
  const f=group.finding;
  if(f.includes("Polynomial regular expression")) return "Replace the flagged expression with bounded, linear-time parsing or validation.";
  if(f.includes("Bad HTML filtering regexp")) return "Avoid regex-based HTML filtering; scan parsed source regions or use a bounded parser.";
  if(f.includes("Incomplete string escaping")) return "Use a complete escaping routine that handles every occurrence and relevant character.";
  if(f.includes("Prototype-polluting")) return "Reject dangerous prototype keys and use own-property or null-prototype storage at the assignment boundary.";
  if(f.includes("Information exposure") || f.includes("Exception text reinterpreted")) return "Keep exception text out of generated HTML and expose only sanitized diagnostics.";
  if(f.includes("Useless assignment")) return "Remove the unused assignment while preserving the surrounding control flow.";
  const sentences=f.split(/(?<=[.!?])\s+/).filter(Boolean);
  return sentences.at(-1) ?? "Apply the narrowest correction supported by the review evidence.";
}
