  const badge=lines.find(x=>x.includes("Badge") && x.includes("</sub>"));
  if(badge)return badge.replace(/<[^>]+>/g,"").replace(/!\[[^\]]*\]\([^)]*\)/g,"").trim().slice(0,180);
  return (lines[0]||"").replace(/[#*_`]/g,"").slice(0,180);
}
